def span(text,signature):
 start=text.index(signature);first=text.index('{',start);depth=0
 # Extract unchanged complete function text; these selected source spans have no braces in literals/comments.
 for pos in range(first,len(text)):
  if text[pos]=='{':depth+=1
  elif text[pos]=='}':
   depth-=1
   if depth==0:return text[start:pos+1]
 raise ValueError('unclosed source span '+signature)
